const request = ($json && typeof $json === 'object' && $json.body !== undefined) ? ($json.body ?? {}) : ($json ?? {});

const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const truthy = (value) => ['1', 'true', 'yes', 'y', 'on'].includes(clean(value).toLowerCase());
const realm = clean(request.realm ?? request.tenant ?? $env.N8N_REALM ?? $env.N8N_ENV_REALM);
const desiredState = clean(request.desired_state ?? request.desiredState ?? 'up').toLowerCase();
const dryRun = request.dry_run === undefined && request.dryRun === undefined ? true : truthy(request.dry_run ?? request.dryRun);
const allowServiceChange = truthy(request.allow_service_change ?? request.allowServiceChange);

if (!realm) throw new Error('realmは必須です');
if (desiredState !== 'up') throw new Error('構成復旧ではdesired_state=upを指定してください');
if (!dryRun && !allowServiceChange) throw new Error('dry_run=falseの場合はallow_service_change=trueが必要です');

const changeId = clean(request.change_id ?? request.changeId) || '未割り当て';
const issueUrl = clean(request.issue_url ?? request.issueUrl);
const mrUrl = clean(request.mr_url ?? request.mrUrl);
const correlationId = clean(request.correlation_id ?? request.correlationId ?? request.trace_id ?? request.traceId);
const detectedCommit = clean(request.detected_commit ?? request.detectedCommit);
const correctionCommit = clean(request.correction_commit ?? request.correctionCommit);

const tests = [
  { name: 'schema_validation', display_name_ja: '入力スキーマ検証', status: 'passed', status_ja: '合格', detail: 'サービスはSulu、復旧後のdesired_stateはupです' },
  { name: 'change_traceability', display_name_ja: '変更トレーサビリティ', status: (issueUrl || mrUrl) ? 'passed' : 'warning', status_ja: (issueUrl || mrUrl) ? '合格' : '警告', detail: (issueUrl || mrUrl) ? 'GitLabのIssueまたはMR証跡を関連付けました' : 'GitLabのIssue/MR URLが指定されていません' },
  { name: 'execution_guard', display_name_ja: '実行許可ガード', status: dryRun || allowServiceChange ? 'passed' : 'failed', status_ja: dryRun || allowServiceChange ? '合格' : '不合格', detail: dryRun ? '非破壊ドライランを強制しています' : '実サービス変更の明示許可を確認しました' },
  { name: 'rollback_readiness', display_name_ja: 'ロールバック準備', status: 'passed', status_ja: '合格', detail: '最後に正常だったGitコミットを復元し、Suluを起動します' }
];

return [{ json: {
  ok: true,
  workflow_id: 'wf.sulu_configuration_recovery',
  service: 'sulu', realm, desired_state: desiredState, dry_run: dryRun, allow_service_change: allowServiceChange,
  correlation_id: correlationId || null,
  change: {
    change_id: changeId, source: 'gitlab', issue_url: issueUrl || null, merge_request_url: mrUrl || null,
    detected_commit: detectedCommit || null, correction_commit: correctionCommit || null,
    detected_diff: { desired_state: { from: 'up', to: 'down' } }, correction_diff: { desired_state: { from: 'down', to: 'up' } }
  },
  assessment: {
    risk_level: 'high', risk_level_ja: '高', impact_scope: 'infra', impact_scope_ja: 'インフラ',
    affected_cis: ['sulu-service', 'sulu-alb-target-group', 'sulu-runtime-config'], tests,
    rollback_plan: '最後に正常だったGitLabコミットを復元し、Sulu Service Controlをaction=upで実行します。'
  },
  report_ja: {
    title: 'シナリオ2: GitLab構成誤変更からのCAB承認付きSulu復旧',
    service: 'Sulu',
    desired_state: '稼働（up）',
    execution_mode: dryRun ? '非破壊ドライラン' : '実サービス変更',
    change_id: changeId,
    risk: '高',
    impact_scope: 'インフラ'
  }
} }];

const plan = $json ?? {};
const backend = String(plan.execution_backend ?? $env.EXASTRO_ITA_DEFAULT_BACKEND ?? 'service-control').trim().toLowerCase();
if (plan.dry_run) {
  return [{ json: { ...plan, execution_backend: backend, status: 'validated', status_ja: '検証済み', simulated: true, applied: false, report_ja: { ...plan.report_ja, result: '検証合格', service_change: '未実施' }, verification: { status: 'passed', status_ja: '合格', mode: 'dry-run', mode_ja: '非破壊ドライラン', service_change_performed: false, service_change_performed_ja: '未実施' } } }];
}

if (backend === 'exastro') {
  const required = (name, value) => { const text = String(value ?? '').trim(); if (!text) throw new Error(`Exastro ITA Conductorの実行には${name}が必要です`); return text; };
  const apiBase = required('EXASTRO_ITA_API_BASE_URL', $env.EXASTRO_ITA_API_BASE_URL).replace(/\/+$/, '');
  const organization = required('EXASTRO_ITA_ORGANIZATION_ID', $env.EXASTRO_ITA_ORGANIZATION_ID);
  const workspace = required('EXASTRO_ITA_WORKSPACE_ID', $env.EXASTRO_ITA_WORKSPACE_ID);
  const menu = String($env.EXASTRO_ITA_CONDUCTOR_MENU || 'conductor_list').trim();
  const conductorName = required('EXASTRO_ITA_CONDUCTOR_NAME', $env.EXASTRO_ITA_CONDUCTOR_NAME);
  const operationName = required('EXASTRO_ITA_OPERATION_NAME', $env.EXASTRO_ITA_OPERATION_NAME);
  const userId = required('EXASTRO_ITA_USER_ID', $env.EXASTRO_ITA_USER_ID);
  const roles = required('EXASTRO_ITA_ROLES_BASE64', $env.EXASTRO_ITA_ROLES_BASE64);
  const headers = { 'User-Id': userId, Roles: roles, Language: 'ja' };
  const accessToken = String($env.EXASTRO_ITA_ACCESS_TOKEN || '').trim();
  if (accessToken) headers.Authorization = `Bearer ${accessToken}`;
  const executeUrl = `${apiBase}/api/${encodeURIComponent(organization)}/workspaces/${encodeURIComponent(workspace)}/ita/menu/${encodeURIComponent(menu)}/conductor/execute/`;
  const conductorResponse = await this.helpers.httpRequest({ method: 'POST', url: executeUrl, json: true, headers, body: { conductor_class_name: conductorName, operation_name: operationName, conductor_data: { service: 'sulu', realm: plan.realm, desired_state: 'up', correlation_id: plan.correlation_id } }, timeout: 30000 });
  const conductorInstanceId = conductorResponse?.data?.conductor_instance_id ?? conductorResponse?.conductor_instance_id ?? null;
  if (!conductorInstanceId) throw new Error(`Exastro ITAからconductor_instance_idが返されませんでした: ${JSON.stringify(conductorResponse)}`);
  const serviceControlBase = required('SERVICE_CONTROL_API_BASE_URL', $env.SERVICE_CONTROL_API_BASE_URL).replace(/\/+$/, '');
  let serviceStatus = null;
  for (let attempt = 0; attempt < 60; attempt += 1) {
    serviceStatus = await this.helpers.httpRequest({ method: 'GET', url: `${serviceControlBase}/status`, json: true, qs: { service: 'sulu', realm: plan.realm }, timeout: 30000 });
    if (Number(serviceStatus?.desiredCount ?? 0) >= 1 && Number(serviceStatus?.runningCount ?? 0) >= 1) break;
    await new Promise((resolve) => setTimeout(resolve, 5000));
  }
  const verified = Number(serviceStatus?.desiredCount ?? 0) >= 1 && Number(serviceStatus?.runningCount ?? 0) >= 1;
  if (!verified) throw new Error(`Exastro Conductor要求後にSuluの復旧を確認できませんでした: ${JSON.stringify(serviceStatus)}`);
  return [{ json: { ...plan, execution_backend: backend, status: 'applied', status_ja: '適用済み', simulated: false, applied: true, report_ja: { ...plan.report_ja, result: '復旧適用合格', service_change: '実施済み' }, conductor: { instance_id: conductorInstanceId, response: conductorResponse }, service_control_response: serviceStatus, verification: { status: 'passed', status_ja: '合格', mode: 'exastro-conductor', mode_ja: 'Exastro Conductor実行', service_change_performed: true, service_change_performed_ja: '実施済み' } } }];
}

if (backend !== 'service-control') throw new Error(`未対応の実行バックエンドです: ${backend}`);
const rawBase = String($env.N8N_WEBHOOK_BASE_URL || ($env.N8N_PUBLIC_API_BASE_URL ? `${String($env.N8N_PUBLIC_API_BASE_URL).replace(/\/+$/, '')}/webhook` : '')).replace(/\/+$/, '');
if (!rawBase) throw new Error('N8N_WEBHOOK_BASE_URLまたはN8N_PUBLIC_API_BASE_URLが必要です');
const response = await this.helpers.httpRequest({ method: 'POST', url: `${rawBase}/sulu/service-control`, json: true, body: { action: 'up', realm: plan.realm }, timeout: 30000 });
const verified = response?.status === 'ok' && response?.action === 'up';
if (!verified) throw new Error(`Suluの起動確認に失敗しました: ${JSON.stringify(response)}`);
return [{ json: { ...plan, execution_backend: backend, status: 'applied', status_ja: '適用済み', simulated: false, applied: true, report_ja: { ...plan.report_ja, result: '復旧適用合格', service_change: '実施済み' }, service_control_response: response, verification: { status: 'passed', status_ja: '合格', mode: 'service-control', mode_ja: 'Sulu Service Control実行', service_change_performed: true, service_change_performed_ja: '実施済み' } } }];
